class Solution {
public:
    int leftMostColumnWithOne(BinaryMatrix& binaryMatrix) {
        vector<int> dimensions = binaryMatrix.dimensions();
        int rows = dimensions[0];
        int cols = dimensions[1];
        int r = 0;
        int c = cols - 1;
        int answer = -1;
        while (r < rows && c >= 0) {
            if (binaryMatrix.get(r, c) == 1) {
                answer = c;
                --c;
            } else {
                ++r;
            }
        }
        return answer;
    }
};
